// mathUtils.js
export const PI = 3.14159;
export function poleKola(promien) {
  return PI * promien ** 2;
}

// inny-plik.js
import { poleKola } from "./mathUtils.js";
console.log(poleKola(7)); // ok. 153.94

// mathUtils.js
export function dodaj(a, b) { return a + b; }
export function odejmij(a, b) { return a - b; }

// inny-plik.js
import { dodaj, odejmij } from "./mathUtils.js";
console.log(dodaj(100, 23));   // 123
console.log(odejmij(100, 23)); // 77

// stringUtils.js
export function capitalize(str) { return str.charAt(0).toUpperCase() + str.slice(1); }
export function slugify(str) { return str.toLowerCase().trim().replace(/\s+/g, "-"); }

// inny-plik.js
import { capitalize, slugify } from "./stringUtils.js";
console.log(capitalize("kurs"));            // "Kurs"
console.log(slugify("  Moj   Kurs JS  "));  // "moj-kurs-js"

// mathUtils.js
export const PI = 3.14159;

// inny-plik.js
import { PI as Ludolfina } from "./mathUtils.js";
console.log(Ludolfina); // 3.14159

// stringUtils.js
export const WERSJA = "1.0.0";

// inny-plik.js
import { WERSJA as wersjaBiblioteki } from "./stringUtils.js";
console.log(wersjaBiblioteki); // "1.0.0"

// mathUtils.js
export function procent(wartosc, proc) { return (wartosc * proc) / 100; }

// inny-plik.js
import { procent } from "./mathUtils.js";
console.log(procent(200, 15)); // 30

// stringUtils.js
export function powtorz(str, n) { return str.repeat(n); }

// inny-plik.js
import { powtorz } from "./stringUtils.js";
console.log(powtorz("ab", 3)); // "ababab"

// mathUtils.js eksportuje funkcje pod nazwa 'dodaj'
export function dodaj(a, b) { return a + b; }

// probujac zaimportowac pod INNA nazwa BEZ uzycia 'as':
// import { suma } from "./mathUtils.js"; // BLEDNA nazwa - w pliku nie ma 'suma'
// -> SyntaxError: modul nie eksportuje nazwy 'suma' (blad przy ladowaniu modulow)

// Import nazwany dziala jak 'wyszukiwanie' KONKRETNEJ nazwy w module
// zrodlowym - silnik JS szuka dokladnie takiej nazwy, jaka zostala
// uzyta po export. Jesli nazwy sie nie zgadzaja (i nie uzyto aliasu
// przez 'as'), silnik zglasza SyntaxError jeszcze przed wykonaniem kodu.

// geometria.js
export const poleProstokata = (a, b) => a * b;
export const obwodProstokata = (a, b) => 2 * (a + b);

// main.js
import { poleProstokata, obwodProstokata } from "./geometria.js";
console.log(poleProstokata(3, 5), obwodProstokata(3, 5)); // -> 15 16

// tablice.js
export const suma = t => t.reduce((a, b) => a + b, 0);
export const srednia = t => suma(t) / t.length;

// main.js
import { suma as sumaTablicy, srednia as sredniaTablicy } from "./tablice.js";
console.log(sumaTablicy([2, 4, 6]), sredniaTablicy([2, 4, 6])); // -> 12 4

// a.js
export const dodaj = (a, b) => a + b;

// main.js
import { dodaj as dodajZModulu } from "./a.js";
const dodaj = (a, b) => "lokalna " + (a + b);

console.log(dodaj(1, 2));         // -> lokalna 3
console.log(dodajZModulu(1, 2));  // -> 3

// config.js
export const host = "localhost";
export const port = 8080;
export const tryb = "dev";

// main.js
import { host, port, tryb } from "./config.js";
console.log(host + ":" + port, tryb); // -> localhost:8080 dev

// konto.js
export class Konto {
  constructor(saldo) { this.saldo = saldo; }
  wplac(kwota) { this.saldo += kwota; }
}

// main.js
import { Konto } from "./konto.js";
const konto = new Konto(100);
konto.wplac(50);
console.log(konto.saldo); // -> 150

// a.js
export const dodaj = (a, b) => a + b;

// main.js
// import { Dodaj } from "./a.js"; // -> SyntaxError: brak eksportu o nazwie Dodaj
import { dodaj } from "./a.js";
console.log(dodaj(1, 2)); // -> 3

// a.js
export const pierwsza = 1;
export const druga = 2;

// main.js
import { druga, pierwsza } from "./a.js";
console.log(pierwsza, druga); // -> 1 2

// a.js
export const a = () => "a";
export const b = () => "b";
export const c = () => "c";
export const d = () => "d";

// main.js
