  a,
  b,
  c,
  d,
} from "./a.js";
console.log(a() + b() + c() + d()); // -> abcd

// a.js
export const dodaj = (a, b) => a + b;

// main.js
import { dodaj as dodajModulowe } from "./a.js";
// const dodajModulowe = 1; // -> SyntaxError: nazwa juz zadeklarowana
const dodaj = 1;
console.log(dodaj, dodajModulowe(2, 3)); // -> 1 5

// pieniadze.js
export const waluta = "zl";
export function formatuj(n) {
  return n + " " + waluta;
}

// main.js
import { formatuj, waluta } from "./pieniadze.js";
console.log(formatuj(25), waluta); // -> 25 zl zl

// ustawienia.js
export const ustawienia = { jezyk: "pl" };

// main.js
import { ustawienia } from "./ustawienia.js";
ustawienia.jezyk = "en";
console.log(ustawienia.jezyk); // -> en
// ustawienia = {} -> TypeError (nie mozna przypisac do importu), ale pole obiektu mozna zmienic.

// tekst.js
export const wielka = s => s.toUpperCase();

// powitanie.js
import { wielka } from "./tekst.js";
export const powitaj = imie => "Czesc, " + wielka(imie);

// main.js
import { powitaj } from "./powitanie.js";
console.log(powitaj("ola")); // -> Czesc, OLA

// tekst.js
function czysc(s) {
  return s.trim();
}
export function normalizuj(s) {
  return czysc(s).toLowerCase();
}

// main.js
import { normalizuj } from "./tekst.js";
console.log(normalizuj("  ALA  ")); // -> ala

// statystyka.js
export const min = t => Math.min(...t);
export const max = t => Math.max(...t);

// main.js
import { min as najmniejsza, max as najwieksza } from "./statystyka.js";
console.log(najmniejsza([4, 9, 2]), najwieksza([4, 9, 2])); // -> 2 9

// walidacja.js
export const czyEmail = s => s.includes("@");
export const czyDlugie = s => s.length >= 8;
export const czyLiczba = s => /^\d+$/.test(s);

// main.js
import { czyEmail, czyDlugie, czyLiczba } from "./walidacja.js";
const haslo = "abc12345";
console.log(czyEmail(haslo), czyDlugie(haslo), czyLiczba(haslo)); // -> false true false

// a.js
export const podwoj = x => x * 2;

// main.js
import { podwoj } from "./a.js";
console.log([1, 2, 3].map(podwoj)); // -> [2, 4, 6]

// a.js
export function dodaj(a, b) { return a + b; }

// main.js
import { dodaj } from "./a.js";
console.log(dodaj.name, dodaj.length); // -> dodaj 2

// dane.js
export const kolory = ["czerwony", "zielony", "niebieski"];

// main.js
import { kolory } from "./dane.js";
const [pierwszy, , ostatni] = kolory;
console.log(pierwszy, ostatni); // -> czerwony niebieski

// dane.js
export const uzytkownik = { imie: "Jan", wiek: 30 };

// main.js
import { uzytkownik } from "./dane.js";
const { imie, wiek } = uzytkownik;
console.log(imie, wiek); // -> Jan 30

// a.js
export const nazwany1 = 1;
export const nazwany2 = 2;
export default "domyslny";

// main.js
import cokolwiek, { nazwany1, nazwany2 } from "./a.js";
console.log(cokolwiek, nazwany1, nazwany2); // -> domyslny 1 2
// nazwane: klamry i dokladna nazwa (albo alias); domyslny: bez klamer, dowolna nazwa, tylko jeden na plik

// a.js
export default function () { return "dom"; }

// main.js
import { default as x } from "./a.js";
import y from "./a.js";
console.log(x(), y(), x === y); // -> dom dom true

// a.js
export const f = () => 1;

// b.js
import { f } from "./a.js";
export const fZB = f;

// c.js
import { f } from "./a.js";
export const fZC = f;

// main.js
import { fZB } from "./b.js";
import { fZC } from "./c.js";
console.log(fZB === fZC); // -> true

